          ]
        ,
          "line": "p3:L19"
        }
      ,
        {
          "key": "안전취급요령",
          "value": "적절한 개인 보호구를 착용하시오."
        ,
          "line": "p3:L20"
        }
      ,
        {
          "key": "안전취급요령",
          "value": "관련 규정 준수."
        ,
          "line": "p3:L21"
        }
      ,
        {
          "key": "안전취급요령",
          "value": "사용 전 취급 설명서를 확보하시오.모든 안전 예방조치 문구를 읽고 이해하기 전에는 취급하지 마시오."
        ,
          "line": "p3:L22"
        }
      ,
        {
          "key": "안전취급요령",
          "value": "정전기 방지용 작업복 및 작업화 착용하시오. 바닥에 접지 하시오."
        ,
          "line": "p3:L24"
        }
      ,
        {
          "key": "나. 안전한 저장 방법",
          "value": "보관 조건"
        ,
          "refs": [
            "S7_STORAGE"
          ]
        ,
          "line": "p3:L26"
        }
      ,
        {
          "key": "보관 조건",
          "value": "충격과 마찰을 피하시오."
        ,
          "line": "p3:L27"
        }
      ,
        {
          "key": "보관 조건",
          "value": "누출여부를 주기적으로 점검하시오."
        ,
          "line": "p3:L28"
        }
      ,
        {
          "key": "보관 조건",
          "value": "건조하고, 서늘하며 환기가 잘 되는 곳에 보관하시오."
        ,
          "line": "p3:L29"
        }
      ,
        {
          "key": "보관 조건",
          "value": "원래의 용기에만 보관하시오."
        ,
          "line": "p3:L30"
        }
      ,
        {
          "key": "보관 조건",
          "value": "정전기 방지 조치를 취하시오."
        ,
          "line": "p3:L31"
        }
      ,
        {
          "key": "보관 조건",
          "value": "직사광선 및 기타 열원을 피해 보관하시오."
        ,
          "line": "p3:L32"
        }
      ]
    ,
